package fraymus.workspace;

import org.json.*;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

public class TaskCost098Test {
    private JSONObject timing(double ms){return TaskCost098.timing(TaskCost089Test.OWNER,10,10+(long)(ms*1e6));}
    private JSONObject decide(String mode,JSONObject model,double spent){return TaskCost098.choose(TaskCost080Test.spec(0),mode,new JSONArray().put(TaskCost085Test.candidate().put("lowerSavingMillis",100000)),TaskCost080Test.workload(),model,"",1,"paired089",timing(spent),new JSONArray());}
    @Test public void defaultAdaptiveNeedsCompleteTaskEvidence(){var d=decide("adaptive",new JSONObject(),1);assertFalse(d.getBoolean("useMemory"));assertEquals("adaptive",d.getString("mode"));assertEquals("direct",d.getString("preferred"));assertFalse(d.has("lookupProof"));}
    @Test public void supportedPositiveBenefitCanStillSelectMemory(){var d=decide("adaptive",TaskCost089Test.model(),1);assertTrue(d.toString(),d.getBoolean("useMemory"));assertTrue(d.getJSONObject("benefit098").getDouble("netLowerSavingMillis")>0);assertEquals(new HashSet<>(Procedure078.FAMILIES),new HashSet<>(Procedure079.order(d)));}
    @Test public void decisionWorkCanEraseOtherwisePositiveSavings(){var d=decide("adaptive",TaskCost089Test.model(),10000);assertFalse(d.getBoolean("useMemory"));assertTrue(d.getJSONObject("cost080").getDouble("lowerSavingMillis")>0);assertTrue(d.getJSONObject("benefit098").getDouble("netLowerSavingMillis")<0);}
    @Test public void laterVerificationWorkIsReservedBeforeSelection(){var d=decide("adaptive",TaskCost089Test.model(),800);assertFalse(d.getBoolean("useMemory"));var b=d.getJSONObject("benefit098");assertEquals(4,b.getInt("verificationPasses"));assertEquals(3200,b.getDouble("decisionAllowanceMillis"),0);assertEquals(800,b.getDouble("reserveMillis"),0);}
    @Test public void calibratedAndDefaultUseSameGate(){var m=TaskCost089Test.model();var a=decide("adaptive",m,1000);var b=decide("calibrated",m,1000);assertTrue(a.put("mode","calibrated").similar(b));}
    @Test public void fixedControlsRemainExplicit(){assertFalse(decide("simple",new JSONObject(),1).getBoolean("useMemory"));assertTrue(decide("memory",new JSONObject(),1).getBoolean("useMemory"));assertFalse(decide("memory",new JSONObject(),1).has("benefit098"));}
    @Test public void staleOutcomesStillPreventAutomaticMemory(){var m=TaskCost089Test.model();var xs=new JSONArray();for(int n=0;n<2;n++)xs.put(new JSONObject().put("id","different-"+n).put("available",true).put("direction","slower"));var d=TaskCost098.choose(TaskCost080Test.spec(0),"adaptive",new JSONArray().put(TaskCost085Test.candidate()),TaskCost080Test.workload(),m,"",1,"paired089",timing(1),xs);assertFalse(d.getBoolean("useMemory"));assertEquals("suspect",d.getJSONObject("freshness090").getString("status"));}
    @Test public void wrongRuntimeAndSavingWorkloadHaveNoInventedBenefit(){assertFalse(decide("adaptive",TaskCost089Test.model().put("profile",new JSONObject()),1).getBoolean("useMemory"));var m=TaskCost089Test.model();for(Object p:m.getJSONArray("pairs"))((JSONObject)p).getJSONObject("workload").put("skill",true);assertFalse(decide("adaptive",TaskCost089Test.setup(m),1).getBoolean("useMemory"));}
    private JSONObject motion(double metres,double degrees){var s=TaskCost080Test.spec(0);var scene=Procedure078.scene(s);for(Object raw:s.getJSONArray("targets")){var t=(JSONObject)raw;var o=WorldPlan.sourceObject(scene,t.getString("sourceId"));var p=new JSONArray(o.getJSONArray("position").toString());p.put(0,p.getDouble(0)+metres);t.put("positionM",p).put("yawDeg",WorldPlan.yaw(o.getJSONArray("rotation"))+degrees);}return s;}
    @Test public void smallMovesDoNotBorrowLongTripSavings(){assertFalse(TaskCost098.movementCovered(motion(2,0),motion(.05,0)));assertFalse(TaskCost098.movementCovered(motion(.05,0),motion(2,0)));assertTrue(TaskCost098.movementCovered(motion(.1,0),motion(.15,0)));}
    @Test public void rotationIsIndependentOfTranslation(){assertFalse(TaskCost098.movementCovered(motion(1,90),motion(1,5)));assertFalse(TaskCost098.movementCovered(motion(0,5),motion(0,90)));assertTrue(TaskCost098.movementCovered(motion(0,30),motion(0,35)));}
    @Test public void everyTargetMustHaveComparableWork(){var a=motion(1,20);var b=motion(1,20);var t=b.getJSONArray("targets").getJSONObject(0);t.put("positionM",WorldPlan.sourceObject(Procedure078.scene(b),t.getString("sourceId")).getJSONArray("position"));assertFalse(TaskCost098.movementCovered(a,b));}
    @Test public void coverageUsesNormalizedMetres(){var a=motion(1,20);var b=WorldFrames.copy(a);var s=b.getJSONObject("source");s.put("units","cm");for(Object raw:s.getJSONArray("objects")){var o=(JSONObject)raw;for(String k:List.of("position","size"))for(int n=0;n<3;n++)o.getJSONArray(k).put(n,o.getJSONArray(k).getDouble(n)*100);}for(String k:List.of("a","b"))for(int n=0;n<3;n++)s.getJSONObject("scaleReference").getJSONArray(k).put(n,s.getJSONObject("scaleReference").getJSONArray(k).getDouble(n)*100);assertTrue(TaskCost098.movementCovered(a,b));}
    @Test public void malformedOrChangedDecisionClocksAreRefused(){assertThrows(JSONException.class,()->TaskCost098.millis(new JSONObject().put("totalMillis",1)));var t=timing(1).put("totalMillis",2);assertThrows(IllegalArgumentException.class,()->TaskCost098.millis(t));assertThrows(IllegalArgumentException.class,()->TaskCost098.timing(TaskCost089Test.OWNER,1,1));assertThrows(IllegalArgumentException.class,()->TaskCost098.timing(TaskCost089Test.OWNER,2,1));}
    @Test public void receiptCannotSilentlyChangeDefaultIntoExplicitControl(){assertThrows(IllegalArgumentException.class,()->TaskCost098.choose(TaskCost080Test.spec(0),"adaptive",new JSONArray(),TaskCost080Test.workload(),new JSONObject(),TaskCost085Test.ID,1,"paired089",timing(1),new JSONArray()));}
}
